-- INDEXES AND TRIGGERS
CREATE INDEX IF NOT EXISTS prep_notes_user_bank_idx ON public.prep_notes USING btree (user_id, bank);
CREATE UNIQUE INDEX IF NOT EXISTS prep_notes_user_bank_title_idx ON public.prep_notes USING btree (user_id, bank, entry_title);
CREATE INDEX IF NOT EXISTS investments_user_idx ON public.investments USING btree (user_id, invested_on DESC) WHERE (deleted_at IS NULL);
CREATE INDEX IF NOT EXISTS ix_kr_checkins_kr_created ON public.kr_checkins USING btree (key_result_id, created_at DESC);
CREATE INDEX IF NOT EXISTS ix_kr_checkins_user_created ON public.kr_checkins USING btree (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS login_events_user_at_idx ON public.login_events USING btree (user_id, at DESC);
CREATE INDEX IF NOT EXISTS shared_items_owner_idx ON public.shared_items USING btree (owner_id, kind, item_ref);
CREATE INDEX IF NOT EXISTS shared_items_recipient_idx ON public.shared_items USING btree (shared_with, due_date);
CREATE UNIQUE INDEX IF NOT EXISTS shared_items_unique_grant_idx ON public.shared_items USING btree (kind, item_ref, shared_with);
CREATE INDEX IF NOT EXISTS day_board_pins_active_idx ON public.day_board_pins USING btree (is_active) WHERE is_active;
-- trigger day_board_pins_touch_trg (needs its function — see FUNCTIONS below)
drop trigger if exists "day_board_pins_touch_trg" on public."day_board_pins";
CREATE TRIGGER day_board_pins_touch_trg BEFORE UPDATE ON public.day_board_pins FOR EACH ROW EXECUTE FUNCTION day_board_pins_touch();
CREATE INDEX IF NOT EXISTS ai_sde_progress_due_idx ON public.ai_sde_progress USING btree (user_id, review_due) WHERE ((review_due IS NOT NULL) AND (NOT is_deleted));
CREATE INDEX IF NOT EXISTS ai_sde_progress_user_idx ON public.ai_sde_progress USING btree (user_id) WHERE (NOT is_deleted);
CREATE UNIQUE INDEX IF NOT EXISTS ai_sde_progress_user_title ON public.ai_sde_progress USING btree (user_id, entry_title);
CREATE INDEX IF NOT EXISTS announcer_items_user_live_idx ON public.announcer_items USING btree (user_id) WHERE (is_deleted = false);
CREATE UNIQUE INDEX IF NOT EXISTS announcer_items_user_client_idx ON public.announcer_items USING btree (user_id, client_id);
CREATE INDEX IF NOT EXISTS interview_topics_user_idx ON public.interview_topics USING btree (user_id, category, "position") WHERE (deleted_at IS NULL);
CREATE INDEX IF NOT EXISTS interview_stories_user_idx ON public.interview_stories USING btree (user_id, "position", created_at) WHERE (deleted_at IS NULL);
