CREATE INDEX IF NOT EXISTS obj_refs_objective_idx ON public.objective_references USING btree (objective_id) WHERE (is_deleted = false);
CREATE INDEX IF NOT EXISTS eisenhower_notes_tasks_plan_date_idx ON public.eisenhower_notes_tasks USING btree (plan_date);
CREATE INDEX IF NOT EXISTS system_design_override_user_idx ON public.system_design_overrides USING btree (user_id) WHERE (deleted_at IS NULL);
CREATE INDEX IF NOT EXISTS interview_qoverride_user_idx ON public.interview_question_overrides USING btree (user_id) WHERE (deleted_at IS NULL);
CREATE INDEX IF NOT EXISTS idx_projects_user_active ON public.projects USING btree (user_id, is_archived);
CREATE UNIQUE INDEX IF NOT EXISTS projects_one_javaprep_per_user ON public.projects USING btree (user_id) WHERE ((name = 'JavaPrep'::text) AND (is_archived = false));
CREATE UNIQUE INDEX IF NOT EXISTS projects_one_aisdeprep_per_user ON public.projects USING btree (user_id) WHERE ((name = 'AISDEPrep'::text) AND (is_archived = false));
