CREATE INDEX IF NOT EXISTS todo_matrix_project_id_idx ON public.todo_matrix USING btree (project_id);
CREATE INDEX IF NOT EXISTS idx_todo_matrix_source_task_id ON public.todo_matrix USING btree (source_task_id);
