CREATE INDEX IF NOT EXISTS quick_bucket_scheduled_idx ON public.quick_bucket USING btree (user_id, scheduled_for);
CREATE INDEX IF NOT EXISTS idx_quick_bucket_backlog_due ON public.quick_bucket USING btree (user_id, backlog_due) WHERE (backlog_due IS NOT NULL);
CREATE INDEX IF NOT EXISTS idx_quick_bucket_source_task ON public.quick_bucket USING btree (source_task_id) WHERE (source_task_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS quick_bucket_user_effort_idx ON public.quick_bucket USING btree (user_id, effort_date) WHERE ((effort_date IS NOT NULL) AND (is_deleted = false));
CREATE INDEX IF NOT EXISTS travel_tasks_user_cat_idx ON public.travel_tasks USING btree (user_id, category);
CREATE INDEX IF NOT EXISTS idx_habit_entries_date ON public.habit_entries USING btree (user_id, plan_date);
-- project_tasks_revised_idx: B had CREATE INDEX project_tasks_revised_idx ON public.project_tasks USING btree (user_id, revised_due_date) WHERE ((is_deleted = false) AND (is_eliminated = false))
drop index if exists public."project_tasks_revised_idx";
