CREATE INDEX IF NOT EXISTS idx_project_tasks_plan_date ON public.project_tasks USING btree (plan_date);
CREATE INDEX IF NOT EXISTS project_tasks_objective_idx ON public.project_tasks USING btree (objective_id) WHERE (objective_id IS NOT NULL);
CREATE INDEX IF NOT EXISTS project_tasks_project_plan_date_idx ON public.project_tasks USING btree (project_id, plan_date) WHERE (is_deleted = false);
CREATE INDEX IF NOT EXISTS idx_task_overrides_lookup ON public.task_overrides USING btree (task_id, task_date);
CREATE INDEX IF NOT EXISTS checklist_items_notify_live_idx ON public.checklist_items USING btree (user_id) WHERE ((is_deleted = false) AND (notify_muted = false));
CREATE INDEX IF NOT EXISTS recurring_tasks_user_idx ON public.recurring_tasks USING btree (user_id) WHERE (is_active = true);
CREATE INDEX IF NOT EXISTS idx_reference_tags ON public.reference_links USING gin (tags);
CREATE INDEX IF NOT EXISTS idx_reference_user ON public.reference_links USING btree (user_id);
CREATE INDEX IF NOT EXISTS project_subtasks_id_idx ON public.project_subtasks USING btree (id);
CREATE INDEX IF NOT EXISTS idx_ref_activity_log_card ON public.ref_activity_log USING btree (bill_id);
CREATE INDEX IF NOT EXISTS idx_habit_goal_lookup ON public.habit_goal_history USING btree (habit_id, effective_from DESC);
CREATE INDEX IF NOT EXISTS idx_portfolio_txn_user ON public.portfolio_transactions USING btree (user_id);

commit;


